<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $scorm->title }}</title><style>html,body{margin:0;height:100%;background:#111;font-family:Arial,sans-serif}.bar{height:48px;background:#fff;display:flex;align-items:center;gap:16px;padding:0 16px;border-bottom:1px solid #ddd}.bar a{text-decoration:none;color:#222}.title{font-weight:700;flex:1}.frame{width:100%;height:calc(100% - 49px);border:0;background:#fff}</style></head><body><div class="bar"><a href="{{ route('home') }}">← Педслово</a><div class="title">{{ $scorm->title }}</div><span>SCORM {{ $scorm->version }}</span></div><iframe id="scormFrame" class="frame" src="{{ asset('storage/'.$scorm->storage_path.'/'.$scorm->launch_path) }}" allowfullscreen></iframe><script>
const endpoint=@json(route('scorm.commit',$attempt)); const token=@json(csrf_token()); const store={}; let initialized=false;
function commit(){return fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':token,'Accept':'application/json'},body:JSON.stringify({data:store}),keepalive:true}).then(()=>true).catch(()=>false)}
function getValue(k){return Object.prototype.hasOwnProperty.call(store,k)?String(store[k]):''} function setValue(k,v){store[k]=String(v);return 'true'}
window.API={LMSInitialize:function(){initialized=true;return 'true'},LMSFinish:function(){commit();initialized=false;return 'true'},LMSGetValue:function(k){return getValue(k)},LMSSetValue:function(k,v){return setValue(k,v)},LMSCommit:function(){commit();return 'true'},LMSGetLastError:function(){return '0'},LMSGetErrorString:function(){return 'No error'},LMSGetDiagnostic:function(){return ''}};
window.API_1484_11={Initialize:function(){initialized=true;return 'true'},Terminate:function(){commit();initialized=false;return 'true'},GetValue:function(k){return getValue(k)},SetValue:function(k,v){return setValue(k,v)},Commit:function(){commit();return 'true'},GetLastError:function(){return '0'},GetErrorString:function(){return 'No error'},GetDiagnostic:function(){return ''}};
fetch(@json(route('scorm.state',$attempt)),{headers:{'Accept':'application/json'}}).then(r=>r.json()).then(x=>{if(x.data)Object.assign(store,x.data)}).catch(()=>{}); window.addEventListener('beforeunload',()=>commit()); setInterval(()=>{if(initialized)commit()},30000);
</script></body></html>
